'use strict';

// MODULES //

var rtrim = require( '@stdlib/string/right-trim' );
var repeat = require( '@stdlib/string/repeat' );
var format = require( '@stdlib/string/format' );
var validate = require( './validate.js' );
var BREAK_CLASSES = require( './break_classes.json' );


// FUNCTIONS //

/**
* Determines whether a break opportunity exists between two adjacent characters.
*
* @private
* @param {string} prev - break class of preceding character
* @param {string} next - break class of following character
* @returns {boolean} whether a break is allowed
*/
function canBreak( prev, next ) {
	if ( next === 'SP' ) {
		return false;
	}
	if ( prev === 'SP' ) {
		return true;
	}
	if ( next === 'CL' ) {
		return false;
	}
	if ( next === 'IS' ) {
		return false;
	}
	if ( prev === 'OP' ) {
		return false;
	}
	if ( next === 'QU' ) {
		return false;
	}
	if ( prev === 'QU' ) {
		return false;
	}
	if ( prev === 'HY' ) {
		return true;
	}
	return false;
}

/**
* Finds break opportunities in a string and returns an array of break unit segments.
*
* @private
* @param {string} text - input string
* @returns {Array<string>} array of break unit segments
*/
function findBreakUnits( text ) {
	var segments;
	var start;
	var prev;
	var curr;
	var len;
	var i;

	len = text.length;
	segments = [];
	start = 0;
	prev = BREAK_CLASSES[ text.charAt( 0 ) ] || 'AL';

	for ( i = 1; i < len; i++ ) {
		curr = BREAK_CLASSES[ text.charAt( i ) ] || 'AL';
		if ( canBreak( prev, curr ) ) {
			segments.push( text.substring( start, i ) );
			start = i;
		}
		prev = curr;
	}
	segments.push( text.substring( start ) );
	return segments;
}

/**
* Wraps a single line of text.
*
* @private
* @param {string} text - line text
* @param {PositiveInteger} contentWidth - available content width
* @param {string} prefix - indent prefix string
* @returns {string} wrapped line with indent applied
*/
function wrapLine( text, contentWidth, prefix ) {
	var segments;
	var lines;
	var line;
	var seg;
	var i;

	segments = findBreakUnits( text );
	lines = [];
	line = '';

	for ( i = 0; i < segments.length; i++ ) {
		seg = segments[ i ];
		if ( seg.length === 0 ) {
			continue;
		}
		if ( line.length === 0 ) {
			line = seg;
		} else if ( rtrim( line + seg ).length <= contentWidth ) {
			line += seg;
		} else {
			lines.push( prefix + rtrim( line ) );
			if ( seg.charAt( 0 ) === ' ' ) {
				seg = seg.substring( 1 );
			}
			line = seg;
		}
	}
	if ( line.length > 0 ) {
		lines.push( prefix + rtrim( line ) );
	}
	return lines.join( '\n' );
}


// MAIN //

/**
* Wraps repl text.
*
* @param {string} text - input text
* @param {Object} [options] - options
* @param {NonNegativeInteger} [options.indent=4] - number of leading spaces per output line
* @param {PositiveInteger} [options.maxWidth=80] - total line width limit
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide valid options
* @throws {RangeError} `options.maxWidth` must be greater than `options.indent`
* @returns {string} wrapped text with indent applied to each line
*
* @example
* var out = wrap( 'This is a short line.' );
* // returns '    This is a short line.'
*/
function wrap( text, options ) {
	var contentWidth;
	var output;
	var prefix;
	var lines;
	var opts;
	var line;
	var err;
	var i;

	opts = {
		'indent': 4,
		'maxWidth': 80
	};
	if ( arguments.length > 1 ) {
		err = validate( opts, options );
		if ( err ) {
			throw err;
		}
	}
	contentWidth = opts.maxWidth - opts.indent;
	if ( contentWidth <= 0 ) {
		throw new RangeError( format( 'invalid option. `%s` must be greater than `%s`. %s: `%u`. %s: `%u`.', 'maxWidth', 'indent', 'maxWidth', opts.maxWidth, 'indent', opts.indent ) );
	}
	if ( text.length === 0 ) {
		return '';
	}
	prefix = repeat( ' ', opts.indent );
	lines = text.split( '\n' );
	output = [];
	for ( i = 0; i < lines.length; i++ ) {
		line = lines[ i ];
		if ( line.length === 0 ) {
			output.push( '' );
		} else if ( line.charAt( 0 ) === ' ' || line.charAt( 0 ) === '\t' ) {
			output.push( prefix + line );
		} else {
			output.push( wrapLine( line, contentWidth, prefix ) );
		}
	}
	return output.join( '\n' );
}


// EXPORTS //

module.exports = wrap;
